for c in C:  # 移除舊版
    i = s.find('id="%s"' % c['idv'])
    if i >= 0:
        a = s.rfind('<details class="it"', 0, i); depth = 0
        for m in re.finditer(r'<details|</details>', s[a:]):
            depth += 1 if m.group() == '<details' else -1
            if depth == 0: b = a + m.end(); break
        s = s[:a] + s[b:]
# 插在 #predlist 結尾
a = s.index('id="predlist"'); st = s.index('>', a) + 1; depth = 1
for mm in re.finditer(r'<div\b|</div>', s[st:]):
    depth += 1 if mm.group().startswith('<div') else -1
    if depth == 0: end = st + mm.start(); break
blocks, fulls = [], {}
for c in C:
    b, f = block(c); blocks.append(b); fulls[c['key']] = f
s = s[:end] + ''.join(blocks) + s[end:]
open(src, 'w', encoding='utf-8').write(s)

